create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;
alter table public.profiles add column if not exists email text;
update public.profiles p set email=u.email from auth.users u where u.id=p.id and p.email is distinct from u.email;
create or replace function private.is_active_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'::public.app_role and p.is_active=true); $$;
revoke all on function private.is_active_admin() from public,anon;
grant execute on function private.is_active_admin() to authenticated;
drop policy if exists "profile read admins" on public.profiles;
create policy "profile read admins" on public.profiles for select to authenticated using ((select private.is_active_admin()));
drop policy if exists "profile update admins" on public.profiles;
create policy "profile update admins" on public.profiles for update to authenticated using ((select private.is_active_admin())) with check ((select private.is_active_admin()));
revoke insert,update,delete on public.profiles from authenticated;
grant select on public.profiles to authenticated;
grant update (role,is_active) on public.profiles to authenticated;
create or replace function private.handle_new_auth_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,email,display_name,role,is_active) values(new.id,new.email,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),split_part(coalesce(new.email,''),'@',1),'Хэрэглэгч'),'viewer'::public.app_role,true) on conflict(id) do update set email=excluded.email; return new; end; $$;
revoke all on function private.handle_new_auth_user() from public,anon,authenticated;
drop trigger if exists on_auth_user_created_mine_control on auth.users;
create trigger on_auth_user_created_mine_control after insert on auth.users for each row execute function private.handle_new_auth_user();
create or replace function private.prevent_last_admin_removal() returns trigger language plpgsql security definer set search_path='' as $$ begin if old.role='admin'::public.app_role and old.is_active=true and (new.role<>'admin'::public.app_role or new.is_active=false) and (select count(*) from public.profiles p where p.role='admin'::public.app_role and p.is_active=true)<=1 then raise exception 'Сүүлийн идэвхтэй администраторыг эрхгүй болгох боломжгүй.'; end if; return new; end; $$;
revoke all on function private.prevent_last_admin_removal() from public,anon,authenticated;
drop trigger if exists prevent_last_admin_removal on public.profiles;
create trigger prevent_last_admin_removal before update of role,is_active on public.profiles for each row execute function private.prevent_last_admin_removal();
